<?php namespace App\Features\Auth\Livewire;use Livewire\Component;use App\Features\Auth\Actions\LoginUserAction;use Illuminate\Support\Facades\Auth;
class Login extends Component{public string $username='';public string $password='';public bool $remember=false;public function login(LoginUserAction $action){$this->validate(['username'=>'required','password'=>'required']);if(!$action->execute(['username'=>$this->username,'password'=>$this->password],$this->remember)){$this->addError('username','Username atau password salah.');return;}request()->session()->regenerate();return redirect()->intended(Auth::user()->role==='admin'?'/admin/users':'/stocks');}public function render(){return view('livewire.auth.login')->layout('components.layouts.app');}}
